        raise ValidationFailedError(
            "Selected audio model does not support explicit inputs",
            details={"model": model},
        )
    raw_voice_id = params.get("voice_id")
    if raw_voice_id is not None and not isinstance(raw_voice_id, str):
        raise ValidationFailedError("voice_id must be a string")
    voice_id = str(raw_voice_id or "").strip()
    if model != catalog.AUDIO_SEED_AUDIO_1_0 and not voice_id:
        raise ValidationFailedError(
            "voice_id is required for audio generation",
            details={"model": model},
        )
    try:
        normalized_tts_options = normalize_tts_options(
            params.get("tts_options")
        )
    except PayloadValidationError as exc:
        raise ValidationFailedError(str(exc)) from exc
    if model == catalog.AUDIO_DOUBAO:
        payload: dict[str, Any] = {"text": prompt}
        if voice_id:
            payload["voice"] = voice_id
        return payload
    if model == catalog.AUDIO_ELEVENLABS:
        payload = {"text": prompt}
        if voice_id:
            payload["voice_id"] = voice_id
        model_id = params.get("model_id")
        if isinstance(model_id, str) and model_id:
            payload["model_id"] = model_id
        output_format = params.get("output_format")
        if isinstance(output_format, str) and output_format:
            payload["output_format"] = output_format
        try:
            voice_settings = get_elevenlabs_voice_settings(
                normalized_tts_options
            )
        except PayloadValidationError as exc:
            raise ValidationFailedError(str(exc)) from exc
        if voice_settings:
            payload["voice_settings"] = voice_settings
        if model_id != "eleven_v3":
            previous_text = params.get("prev_text") or params.get(
                "previous_text"
            )
            next_text = params.get("next_text")
            if isinstance(previous_text, str) and previous_text.strip():
                payload["previous_text"] = previous_text
            if isinstance(next_text, str) and next_text.strip():
                payload["next_text"] = next_text
        return payload
    if model == catalog.AUDIO_MINIMAX:
        if len(prompt) >= MINIMAX_TTS_MAX_TEXT_LENGTH:
            raise ValidationFailedError(
                "MiniMax TTS text must be less than "
                f"{MINIMAX_TTS_MAX_TEXT_LENGTH} characters"
            )
        provider_model = params.get("provider_model")
        payload = {
            "text": prompt,
            "model": resolve_minimax_tts_model(
                provider_model
                if isinstance(provider_model, str) and provider_model
                else None,
                configured_default=(
                    get_app_config().creation.minimax_tts_model
                ),
            ),
            "language_boost": str(params.get("language_boost") or "auto"),
        }
        if voice_id:
            payload["voice_id"] = voice_id
        return payload
    if model == catalog.AUDIO_SEED_AUDIO_1_0:
        if params.get("duration_seconds") is not None:
            raise UnsatisfiableConstraintsError(
                "Seed Audio cannot guarantee an exact output duration",
                details={
                    "model": model,
                    "duration_seconds": params["duration_seconds"],
                },
            )
        if len(prompt) > 2048:
            raise ValidationFailedError(
                "Seed Audio prompt exceeds 2048 characters"
            )
        by_type = _group_inputs(inputs)
        audio_inputs = by_type["audio"] + by_type["music"]
        image_inputs = by_type["image"]
        if by_type["video"]:
            raise ValidationFailedError("Seed Audio does not accept video inputs")
        if audio_inputs and image_inputs:
            raise ValidationFailedError(
                "Seed Audio cannot mix audio and image references"
            )
        if len(audio_inputs) > 3 or len(image_inputs) > 1:
            raise ValidationFailedError(
                "Seed Audio input limit exceeded",
                details={
                    "audio_count": len(audio_inputs),
                    "image_count": len(image_inputs),
                },
            )
        for index, item in enumerate(image_inputs, start=1):
            validation_error = validate_seed_audio_reference_image_url(
                str(item.get("uri") or ""),
                f"Seed Audio reference_image_infos[{index}]",
            )
            if validation_error:
                raise ValidationFailedError(
                    validation_error,
                    details={"resource_id": item["resource_id"]},
                )
        references: list[dict[str, Any]] = []
        for item in audio_inputs:
            start_time_ms = item.get("start_time_ms")
            end_time_ms = item.get("end_time_ms")
            reference = {"audio_url": item["uri"]}
            if start_time_ms is not None or end_time_ms is not None:
                normalized_start_time_ms = int(start_time_ms or 0)
                normalized_end_time_ms = int(
                    end_time_ms
                    if end_time_ms is not None
                    else normalized_start_time_ms + 30_000
                )
                if normalized_end_time_ms <= normalized_start_time_ms:
                    raise ValidationFailedError(
                        "Seed Audio reference end_time_ms must be greater than "
                        "start_time_ms",
                        details={"resource_id": item["resource_id"]},
                    )
                if normalized_end_time_ms - normalized_start_time_ms > 30_000:
                    raise ValidationFailedError(
                        "Seed Audio reference duration cannot exceed 30000ms",
                        details={"resource_id": item["resource_id"]},
                    )
                reference["start_time_ms"] = normalized_start_time_ms
                reference["end_time_ms"] = normalized_end_time_ms
            references.append(reference)
        references.extend({"image_url": item["uri"]} for item in image_inputs)
        if voice_id:
            if references:
                raise ValidationFailedError(
                    "Seed Audio voice_id cannot be mixed with references"
                )
            references.append({"speaker": voice_id})
        payload = {
            "model": "seed-audio-1.0",
            "text_prompt": format_seed_audio_prompt(
                prompt,
                audio_inputs,
            ),
            "audio_config": params.get("audio_config")
            or {"format": "mp3", "sample_rate": 24000},
        }
        if references:
            payload["references"] = references
        return payload
    raise AssertionError(f"Unhandled audio model: {model}")

